// Récupérer la réponse de l'agent
const response = $input.first().json;

// Si la réponse a un champ 'output' (pour AI Agent)
let jsonData = response;

if (response.output) {
  try {
    // Nettoyer la réponse
    let cleanText = response.output
      .replace(/```json\s*/g, '')
      .replace(/```\s*/g, '')
      .trim();

    // Extraire le JSON entre { et }
    const match = cleanText.match(/\{.*\}/s);
    if (match) {
      jsonData = JSON.parse(match[0]);
    } else {
      jsonData = JSON.parse(cleanText);
    }
  } catch (e) {
    // Si c'est déjà un objet
    jsonData = response.output;
    if (typeof jsonData === 'string') {
      try {
        jsonData = JSON.parse(jsonData);
      } catch (e2) {
        jsonData = response;
      }
    }
  }
}

// Si la réponse a un champ 'text' (pour d'autres modèles)
if (response.text) {
  try {
    let cleanText = response.text
      .replace(/```json\s*/g, '')
      .replace(/```\s*/g, '')
      .trim();

    const match = cleanText.match(/\{.*\}/s);
    if (match) {
      jsonData = JSON.parse(match[0]);
    } else {
      jsonData = JSON.parse(cleanText);
    }
  } catch (e) {
    jsonData = response;
  }
}

// Si jsonData est déjà un objet avec les bons champs
if (typeof jsonData === 'object' && jsonData !== null && !jsonData.code_fournisseur) {
  // Essayer d'extraire de la réponse brute
  const str = JSON.stringify(response);
  const match = str.match(/\{.*\}/s);
  if (match) {
    try {
      const parsed = JSON.parse(match[0]);
      if (parsed.code_fournisseur) {
        jsonData = parsed;
      }
    } catch (e) {}
  }
}

// Vérifier les champs requis et ajouter des valeurs par défaut
const required = ['code_fournisseur', 'code_article', 'prix', 'marque', 'statut', 'marque_autorisee', 'dans_le_budget', 'alerte'];
for (const field of required) {
  if (!(field in jsonData) || jsonData[field] === undefined || jsonData[field] === null) {
    if (field === 'alerte') {
      jsonData[field] = null;
    } else if (field === 'marque_autorisee') {
      jsonData[field] = false;
    } else if (field === 'dans_le_budget') {
      jsonData[field] = false;
    } else if (field === 'statut') {
      jsonData[field] = 'Inconnu';
    } else {
      jsonData[field] = 'INCONNU';
    }
  }
}

return [jsonData];

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}

return $input.all();

// Group items by code_article
const grouped = {};

for (const item of $input.all()) {
  const code = item.json.code_article; 

  if (!grouped[code]) {
    grouped[code] = [];
  }
  grouped[code].push(item.json);
}

// Convert to array of groups if needed
const result = Object.keys(grouped).map(code => ({
  code_article: code,
  items: grouped[code],
  count: grouped[code].length
}));

return result;

// Récupérer toutes les marques uniques
const marques = new Set();

for (const item of $input.all()) {
  if (item.json.marque) {
    marques.add(item.json.marque);
  }
}

// Retourner un tableau de marques
return [{ marques: Array.from(marques) }];

